func (t *ChangeLogEntry) Get(primaryKey interface{}) bool {
	// A composite primary key (map[string]interface{}, values also as text)
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		key := changeLogEntryFields.KeyFromMap(pkMap)
		return t.GetByPK(key[0].(int))
	}
	// The primary key itself (a table with one primary key field)
	if key, ok := changeLogEntryFields.KeyFromValue(primaryKey); ok {
		return t.GetByPK([]any{key}[0].(int))
	}

	fmt.Printf("Error: Invalid primary key type for Change_Log_Entry.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

